import{_ as a,o as i,c as l,ag as o}from"./chunks/framework.B12NDdjC.js";const t="/ems_simulate/doc-img/device/device-management/1.png",c="/ems_simulate/doc-img/device/device-management/2.png",r="/ems_simulate/doc-img/device/device-management/3.png",n="/ems_simulate/doc-img/device/device-management/4.png",m="/ems_simulate/doc-img/device/device-management/5.png",s="/ems_simulate/doc-img/device/device-management/6.png",d="/ems_simulate/doc-img/device/device-management/7.png",p="/ems_simulate/doc-img/device/device-management/8.png",h="/ems_simulate/doc-img/device/device-management/9.png",u="/ems_simulate/doc-img/device/device-management/10.png",P=JSON.parse('{"title":"设备管理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/device/device-management.md","filePath":"guide/device/device-management.md","lastUpdated":1771830088000}'),g={name:"guide/device/device-management.md"};function _(b,e,q,k,v,f){return i(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="设备管理" tabindex="-1">设备管理 <a class="header-anchor" href="#设备管理" aria-label="Permalink to &quot;设备管理&quot;">​</a></h1><p>设备模块提供了对模拟器中设备和设备组的全面管理功能。本指南将介绍如何进行设备组管理、设备管理以及测点的导入操作。</p><h2 id="设备组管理" tabindex="-1">设备组管理 <a class="header-anchor" href="#设备组管理" aria-label="Permalink to &quot;设备组管理&quot;">​</a></h2><p>设备组用于对相同类型或相同业务场景的设备进行逻辑分组，方便统一管理。</p><h3 id="添加设备组" tabindex="-1">添加设备组 <a class="header-anchor" href="#添加设备组" aria-label="Permalink to &quot;添加设备组&quot;">​</a></h3><ol><li>在侧边栏，点击设备组区域的“添加”按钮。</li><li>填写设备组名称等基本信息。</li><li>点击“确定”保存。</li></ol><blockquote><p><img src="'+t+'" alt=""></p></blockquote><h3 id="编辑设备组" tabindex="-1">编辑设备组 <a class="header-anchor" href="#编辑设备组" aria-label="Permalink to &quot;编辑设备组&quot;">​</a></h3><ol><li>选择需要编辑的设备组。</li><li>修改设备组的名称和信息。</li><li>点击“确定”保存修改。</li></ol><blockquote><p><img src="'+c+'" alt=""></p></blockquote><h3 id="删除设备组" tabindex="-1">删除设备组 <a class="header-anchor" href="#删除设备组" aria-label="Permalink to &quot;删除设备组&quot;">​</a></h3><ol><li>选择需要删除的设备组。</li><li>点击下拉列表，点击“删除”按钮，在弹出的确认框中确认删除操作。</li><li><strong>注意</strong>：删除设备组会包含它里面的设备以及测点。</li></ol><blockquote><p><img src="'+r+'" alt=""></p></blockquote><h2 id="设备管理-1" tabindex="-1">设备管理 <a class="header-anchor" href="#设备管理-1" aria-label="Permalink to &quot;设备管理&quot;">​</a></h2><p>设备是模拟器中进行数据采集和控制的基本单元。</p><h3 id="添加设备" tabindex="-1">添加设备 <a class="header-anchor" href="#添加设备" aria-label="Permalink to &quot;添加设备&quot;">​</a></h3><ol><li>选中要添加设备的设备组。</li><li>点击“新增主站”或者“新增从站”按钮。</li><li>填写基本参数、连接参数等配置信息。</li><li>点击“确定”完成添加。</li></ol><blockquote><p><img src="'+n+'" alt=""></p></blockquote><h3 id="编辑设备" tabindex="-1">编辑设备 <a class="header-anchor" href="#编辑设备" aria-label="Permalink to &quot;编辑设备&quot;">​</a></h3><ol><li>在设备列表中点击选中需要编辑的设备。</li><li>在右侧修改设备的连接参数或基本信息。</li><li>点击上方“保存配置”按钮。</li></ol><blockquote><p><img src="'+m+'" alt=""></p></blockquote><h3 id="删除设备" tabindex="-1">删除设备 <a class="header-anchor" href="#删除设备" aria-label="Permalink to &quot;删除设备&quot;">​</a></h3><ol><li>在设备列表中选择需要删除的设备，点击右键。</li><li>点击弹出的“删除”按钮。</li><li>确认后即从系统中移除该设备。</li></ol><blockquote><p><img src="'+s+'" alt=""></p></blockquote><h2 id="导入测点" tabindex="-1">导入测点 <a class="header-anchor" href="#导入测点" aria-label="Permalink to &quot;导入测点&quot;">​</a></h2><p>为了方便快速配置设备的数据点，系统支持通过模板或文件批量导入测点信息。</p><ol><li><p>在设备列表中，选择需要导入测点的目标设备。</p></li><li><p>点击“导入测点”按钮。</p></li><li><p>选择准备好的测点配置文件（通常为 Excel 文件）。</p><blockquote><p><img src="'+d+'" alt=""></p></blockquote></li><li><p>上传文件并确认导入。系统将自动解析并在该设备下生成对应的测点。</p><blockquote><p><img src="'+p+'" alt=""></p></blockquote></li></ol><h2 id="设备控制" tabindex="-1">设备控制 <a class="header-anchor" href="#设备控制" aria-label="Permalink to &quot;设备控制&quot;">​</a></h2><h3 id="启动设备" tabindex="-1">启动设备 <a class="header-anchor" href="#启动设备" aria-label="Permalink to &quot;启动设备&quot;">​</a></h3><ol><li><p>在左侧设备树中点击选中需要启动的设备。</p></li><li><p>在右侧的设备详情展示区，点击上方的主操作按钮“开启设备”。</p></li><li><p>设备状态将变更为“运行中”，开始与外部系统进行通讯和数据交互。</p><blockquote><p><img src="'+h+'" alt=""></p></blockquote></li></ol><h3 id="关闭设备" tabindex="-1">关闭设备 <a class="header-anchor" href="#关闭设备" aria-label="Permalink to &quot;关闭设备&quot;">​</a></h3><ol><li><p>在左侧设备树中点击选中正在运行的设备。</p></li><li><p>在右侧的设备详情展示区，点击上方的主操作按钮“停止设备”。</p></li><li><p>设备状态将变更为“停止”，设备连接断开，停止数据交互。</p><blockquote><p><img src="'+u+'" alt=""></p></blockquote></li></ol>',32)])])}const T=a(g,[["render",_]]);export{P as __pageData,T as default};
